CREATE OR REPLACE SEMANTIC VIEW "GOLDEN_DB"."GOLDEN_SCHEMA"."GOLDEN_SEMANTIC"
TABLES (
  DISTRICT AS "GOLDEN_DB"."GOLDEN_SCHEMA"."DISTRICT" PRIMARY KEY ("DISTRICTID"),
  ITEM AS "GOLDEN_DB"."GOLDEN_SCHEMA"."ITEM" PRIMARY KEY ("ITEMID"),
  SALES AS "GOLDEN_DB"."GOLDEN_SCHEMA"."SALES",
  STORE AS "GOLDEN_DB"."GOLDEN_SCHEMA"."STORE_ENRICHED" PRIMARY KEY ("LOCATIONID"),
  TIME AS "GOLDEN_DB"."GOLDEN_SCHEMA"."TIME" PRIMARY KEY ("REPORTINGPERIODID")
)
RELATIONSHIPS (
  STORE_DISTRICTID_DISTRICT_DISTRICTID AS STORE ("DISTRICTID") REFERENCES DISTRICT ("DISTRICTID"),
  SALES_LOCATIONID_STORE_LOCATIONID AS SALES ("LOCATIONID") REFERENCES STORE ("LOCATIONID"),
  SALES_ITEMID_ITEM_ITEMID AS SALES ("ITEMID") REFERENCES ITEM ("ITEMID"),
  SALES_REPORTINGPERIODID_TIME_REPORTINGPERIODID AS SALES ("REPORTINGPERIODID") REFERENCES TIME ("REPORTINGPERIODID")
)
FACTS (
  PRIVATE SALES."MONTHID" AS SALES."MONTHID",
  PRIVATE SALES."SUM_GROSSMARGINAMOUNT" AS SALES."SUM_GROSSMARGINAMOUNT",
  PRIVATE SALES."SUM_REGULAR_SALES_DOLLARS" AS SALES."SUM_REGULAR_SALES_DOLLARS",
  PRIVATE SALES."SUM_MARKDOWN_SALES_DOLLARS" AS SALES."SUM_MARKDOWN_SALES_DOLLARS",
  PRIVATE SALES."SCENARIOID" AS SALES."SCENARIOID",
  PRIVATE SALES."SUM_REGULAR_SALES_UNITS" AS SALES."SUM_REGULAR_SALES_UNITS",
  PRIVATE SALES."SUM_MARKDOWN_SALES_UNITS" AS SALES."SUM_MARKDOWN_SALES_UNITS"
)
DIMENSIONS (
  DISTRICT."DISTRICTID" AS DISTRICT."DISTRICTID",
  DISTRICT."DISTRICT" AS DISTRICT."DISTRICT",
  DISTRICT."DM" AS DISTRICT."DM",
  DISTRICT."DM_PIC_FL" AS DISTRICT."DM_PIC_FL",
  DISTRICT."DM_PIC" AS DISTRICT."DM_PIC",
  DISTRICT."BUSINESSUNITID" AS DISTRICT."BUSINESSUNITID",
  DISTRICT."DMIMAGE" AS DISTRICT."DMIMAGE",
  ITEM."SEGMENT" AS ITEM."SEGMENT",
  ITEM."CATEGORY" AS ITEM."CATEGORY",
  ITEM."BUYER" AS ITEM."BUYER",
  ITEM."FAMILYNANE" AS ITEM."FAMILYNANE",
  ITEM."CATEGORY_CLUSTERS_2" AS ITEM."CATEGORY_CLUSTERS_2" WITH SYNONYMS = ('Category (clusters) 2') COMMENT = 'Clusters for Category',
  STORE."TERRITORY" AS STORE."TERRITORY" WITH SYNONYMS = ('territory', 'state'),
  STORE."POSTALCODE" AS STORE."POSTALCODE" WITH SYNONYMS = ('postal code', 'zip'),
  STORE."OPENDATE" AS STORE."OPENDATE" WITH SYNONYMS = ('open date'),
  STORE."NAME" AS STORE."NAME" WITH SYNONYMS = ('name'),
  STORE."STORENUMBERNAME" AS STORE."STORENUMBERNAME" WITH SYNONYMS = ('store number name'),
  STORE."CITY" AS STORE."CITY" WITH SYNONYMS = ('city', 'calculated column 1'),
  STORE."CHAIN" AS STORE."CHAIN" WITH SYNONYMS = ('chain'),
  STORE."DM" AS STORE."DM" WITH SYNONYMS = ('DM'),
  STORE."DM_PIC" AS STORE."DM_PIC" WITH SYNONYMS = ('DM pic'),
  STORE."DISTRICTID" AS STORE."DISTRICTID" WITH SYNONYMS = ('district ID'),
  STORE."STORE_TYPE" AS STORE."STORE_TYPE" WITH SYNONYMS = ('store type', 'calculated column 1'),
  STORE."OPEN_MONTH" AS STORE."OPEN_MONTH" WITH SYNONYMS = ('open month', 'calculated column 1'),
  TIME."FISCALMONTH" AS TIME."FISCALMONTH" WITH SYNONYMS = ('fiscal month', 'month'),
  TIME."MONTH" AS TIME."MONTH" WITH SYNONYMS = ('business day date'),
  PRIVATE ITEM."ITEMID" AS ITEM."ITEMID",
  PRIVATE SALES."ITEMID" AS SALES."ITEMID",
  PRIVATE SALES."LOCATIONID" AS SALES."LOCATIONID",
  PRIVATE STORE."LOCATIONID" AS STORE."LOCATIONID" WITH SYNONYMS = ('location ID'),
  PRIVATE STORE."CITY_NAME" AS STORE."CITY_NAME" WITH SYNONYMS = ('city name', 'city'),
  STORE."SELLINGAREASIZE" AS STORE."SELLINGAREASIZE" WITH SYNONYMS = ('selling area size'),
  PRIVATE STORE."DISTRICTNAME" AS STORE."DISTRICTNAME" WITH SYNONYMS = ('district name', 'district'),
  STORE."STORENUMBER" AS STORE."STORENUMBER" WITH SYNONYMS = ('store number'),
  PRIVATE TIME."REPORTINGPERIODID" AS TIME."REPORTINGPERIODID" WITH SYNONYMS = ('reporting period ID'),
  TIME."PERIOD" AS TIME."PERIOD" WITH SYNONYMS = ('period'),
  TIME."FISCALYEAR" AS TIME."FISCALYEAR" WITH SYNONYMS = ('fiscal year', 'year'),
  PRIVATE STORE."ALL_COUNTA_STORE_TYPE_NEW_STORE" AS STORE."_ALL_COUNTA_STORE_TYPE_NEW_STORE"
)
METRICS (
  SALES."TEST_MEASURE" AS SUM(SALES.SUM_REGULAR_SALES_UNITS::FLOAT) * 2 COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."REGULAR_SALES_DOLLARS" AS SUM(SALES.SUM_REGULAR_SALES_DOLLARS::FLOAT),
  SALES."MARKDOWN_SALES_DOLLARS" AS SUM(SALES.SUM_MARKDOWN_SALES_DOLLARS::FLOAT),
  SALES."TOTALSALES" AS CASE WHEN (SUM(SALES.SUM_REGULAR_SALES_DOLLARS::FLOAT)) IS NULL AND (SUM(SALES.SUM_MARKDOWN_SALES_DOLLARS::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(SALES.SUM_REGULAR_SALES_DOLLARS::FLOAT)), 0) + COALESCE((SUM(SALES.SUM_MARKDOWN_SALES_DOLLARS::FLOAT)), 0) END,
  SALES."TOTALSALESLY" AS CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."GROSS_MARGIN_THIS_YEAR" AS SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_GROSSMARGINAMOUNT END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."GROSS_MARGIN_THIS_YEAR_PCT" AS (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_GROSSMARGINAMOUNT END::FLOAT)) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END, 0),
  SALES."GROSS_MARGIN_LAST_YEAR" AS SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_GROSSMARGINAMOUNT END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."GROSS_MARGIN_LAST_YEAR_PCT" AS (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_GROSSMARGINAMOUNT END::FLOAT)) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END, 0),
