  SALES."TOTALUNITS" AS CASE WHEN (SUM(SALES.SUM_REGULAR_SALES_UNITS::FLOAT)) IS NULL AND (SUM(SALES.SUM_MARKDOWN_SALES_UNITS::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(SALES.SUM_REGULAR_SALES_UNITS::FLOAT)), 0) + COALESCE((SUM(SALES.SUM_MARKDOWN_SALES_UNITS::FLOAT)), 0) END,
  SALES."TOTAL_UNITS_LAST_YEAR" AS CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."TOTAL_UNITS_THIS_YEAR" AS CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."AVG_DOL_UNIT_TY" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END) <> 0 THEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END, 0) END,
  SALES."AVG_DOL_UNIT_LY" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END) <> 0 THEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END, 0) END,
