  SALES."TOTAL_SALES_VARIANCE" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) IS NULL AND (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) IS NULL THEN NULL ELSE COALESCE((CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END), 0) - COALESCE((CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END), 0) END,
  SALES."TOTAL_SALES_VARIANCE_PCT" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) <> 0 THEN (CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) IS NULL AND (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) IS NULL THEN NULL ELSE COALESCE((CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END), 0) - COALESCE((CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END), 0) END) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END, 0) END,
  SALES."STORE_COUNT" AS COUNT(DISTINCT SALES.LOCATIONID),
  SALES."AVERAGE_UNIT_PRICE" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END) <> 0 THEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END, 0) END,
  SALES."AVERAGE_UNIT_PRICE_LAST_YEAR" AS CASE WHEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END) <> 0 THEN (CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END) / NULLIF(CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_REGULAR_SALES_UNITS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 2 THEN SALES.SUM_MARKDOWN_SALES_UNITS ELSE NULL END::FLOAT)), 0) END, 0) END,
  SALES."TOTALSALESTY" AS CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END WITH SYNONYMS = ('TYS Card') COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALES."THIS_YEAR_SALES" AS CASE WHEN (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL AND (SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)) IS NULL THEN NULL ELSE COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_REGULAR_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) + COALESCE((SUM(CASE WHEN SALES.SCENARIOID = 1 THEN SALES.SUM_MARKDOWN_SALES_DOLLARS ELSE NULL END::FLOAT)), 0) END,
  STORE."AVERAGE_SELLING_AREA_SIZE" AS AVG(STORE.SELLINGAREASIZE) WITH SYNONYMS = ('average selling area size', 'average of selling area size'),
  STORE."NEW_STORES" AS MAX(STORE._ALL_COUNTA_STORE_TYPE_NEW_STORE) WITH SYNONYMS = ('new store'),
  SALES."NEW_STORES_TARGET" AS MAX(14) WITH SYNONYMS = ('new stores target'),
  STORE."TOTAL_STORES" AS COUNT(STORE.STORENUMBERNAME) WITH SYNONYMS = ('total store', 'count of store number name'),
  STORE."OPEN_STORE_COUNT" AS COUNT(STORE.OPENDATE) WITH SYNONYMS = ('open store count', 'count of open date 2'),
  STORE."COUNT_OF_OPENDATE" AS COUNT(STORE.OPENDATE) WITH SYNONYMS = ('count of open date'),
  STORE."SUM_OF_SELLINGAREASIZE" AS SUM(STORE.SELLINGAREASIZE::FLOAT) WITH SYNONYMS = ('selling area size'),
  STORE."SUM_OF_STORENUMBER" AS SUM(STORE.STORENUMBER::FLOAT) WITH SYNONYMS = ('store number'),
  TIME."SUM_OF_PERIOD" AS SUM(TIME.PERIOD::FLOAT) WITH SYNONYMS = ('period'),
  TIME."SUM_OF_FISCALYEAR" AS SUM(TIME.FISCALYEAR::FLOAT) WITH SYNONYMS = ('fiscal year', 'year')
);
